from typing import List

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        freq = Counter(nums)
        max_len = 0

        for x in freq:
            if x == 1:
                count = freq[x]
                if count % 2 == 1:
                    current_max = count
                else:
                    current_max = count - 1
                if current_max > max_len:
                    max_len = current_max
            else:
                current = x
                current_k = 0
                while True:
                    next_val = current * current
                    if next_val not in freq:
                        break
                    if freq[current] >= 2:
                        current_k += 1
                        current = next_val
                    else:
                        break
                current_max = 2 * current_k + 1
                if current_max > max_len:
                    max_len = current_max

        return max_len
