class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        count = 0
        prev = []
        for num in nums:
            curr = []
            curr.append(num)
            for val in prev:
                curr.append(val & num)
            for val in curr:
                if val == k:
                    count += 1
            prev = curr
        return count
