                    for c1 in range(3):
                        for c2 in range(3):
                            if c1 != c2 and c1 != c1_prev and c2 != c2_prev:
                                curr_dp[c1][c2] = min(
                                    curr_dp[c1][c2],
                                    prev_dp[c1_prev][c2_prev] + cost[i][c1] + cost[j][c2]
                                )
            prev_dp = curr_dp

        # Find the minimum value in the last DP table
        return min(min(row) for row in prev_dp)
